 141	    const dynamic_count = std.math.divCeil(
 142	        usize,
 143	        cols - prealloc_columns,
 144	        unit_bits,
 145	    ) catch unreachable;
 146	    if (dynamic_count <= self.dynamic_stops.len) {
 147	        self.cols = cols;
