 151	    try tw.check(.dynamic_alloc);
 152	    const old_len = self.dynamic_stops.len;
 153	    self.dynamic_stops = try alloc.realloc(self.dynamic_stops, dynamic_count);
 154	    @memset(self.dynamic_stops[old_len..], 0);
 155	    self.cols = cols;
 156	}
